var doc = Document;
// Goal: make a change the user can inspect, then take it back cleanly.
// The script side is small; the undo/redo side is two TOOL calls, described in
// steps 3-5. Revit's undo stack is per document and the tools act on the ACTIVE
// document's stack, so run this routed at the active document (omit document_id).

// 1. Run with a label: execute_script { "label": "how-to undo probe" }. Every block
//    the run commits is grouped into ONE undo step named "MCP: how-to undo probe".
//    Without a label the connector derives one from the report, e.g.
//    "MCP: 1 Levels created" (an undo-label-not-applied notice means Revit refused
//    the rename; the work is still one step).
var id = Connector.WithTransaction(doc, () => {
  var lvl = Autodesk.Revit.DB.Level.Create(doc, 44.0);
  lvl.Name = "How-to undo probe";
  return lvl.Id.Value;
});

// 2. Verify the write landed: one level at 44.0; the response's mutations block
//    says net_created 1.
int at44 = 0;
foreach (var e in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  var lvl = e as Autodesk.Revit.DB.Level;
  if (lvl != null && System.Math.Abs(lvl.Elevation - 44.0) < 0.01) at44++;
}

// 3. To take it back: call the `undo` tool with { "instance_id": ..., "confirm": true }.
//    Without confirm it is refused (undo-confirmation-required) because the stack is
//    global to the session: if the person acted after this run, undo reverts THEIR
//    step. The response carries mutations (net_deleted 1 here) and a notice:
//    undo-reverted-connector-work naming "MCP: how-to undo probe", or
//    undo-reverted-other-work if it was not this run -- stop and tell the user.
//    Pass document_id if you expect a particular document to be active; a different
//    active document is refused (undo-wrong-active-document).
// 4. `redo` with confirm: true restores it (mutations net_created 1).
// 5. A second `undo` leaves the model as found. A read-only run in between (like a
//    collector count) does not push an undo step, so the sequence stays intact.
return new { levelId = id, levelsAt44 = at44, undoLabel = "MCP: how-to undo probe" };
